import{z as o,x as s,o as e,c as l,q as A,j as n,D as a,d as r,s as i,S as t}from"./chunks/framework.C8m1ZpeB.js";const V=JSON.parse('{"title":"已实现方差的族谱","description":"","frontmatter":{"title":"已实现方差的族谱","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/hfs-realized-variance-family.md","filePath":"quant/hfs-realized-variance-family.md","lastUpdated":1791413859000}'),d={name:"quant/hfs-realized-variance-family.md"};function h(m,E,p,C,c,_){const B=s("Mermaid");return e(),l("div",null,[E[2]||(E[2]=A('<h1 id="已实现方差的族谱" tabindex="-1">已实现方差的族谱 <a class="header-anchor" href="#已实现方差的族谱" aria-label="Permalink to &quot;已实现方差的族谱&quot;">​</a></h1><div class="epigraph"><p>估计量的族谱不按发表年份排，按两件事排：你在估哪个对象，以及允许谁在场——噪声、跳、不同步，各划出一条支路。</p><footer>—— 据 Barndorff-Nielsen and Shephard, Econometrica 2004；Zhang, Mykland and Aït-Sahalia, JASA 2005 整理</footer></div><p><a href="/quant/slm-map">上一课</a>把统计学习收在信噪比上：样本外只有千分位，协议高于模型——一个含义成立的千分位胜过一万个含义不明的拟合——并把高频统计的估计量谱系指给本课程。本课起转到最便宜也最易用错的一份——逐笔行情——的统计读数。主干已写过<a href="/quant/microstructure-noise">微观结构噪声</a>的机制、<a href="/quant/rv-noise">已实现波动与噪声修正</a>的概览与<a href="/quant/bn-jump-test">Barndorff-Nielsen 跳跃检验</a>的单点；本课程第一课做的是立族谱：把已实现方差一族的估计量按「对象 × 容许的干扰」排成树，后面的课各走进一条支路。后课默认已经读完本课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>二次变差是价格过程波动的自然对象：\\([X]_t=\\int_0^t\\sigma_u^2\\,du+\\sum_{s\\le t}(\\Delta X_s)^2\\)，连续部分是积分波动 \\(IV\\)，跳跃部分是瞬间贡献。把日内收益平方加总的 \\(\\mathrm{RV}_n=\\sum_i r_i^2\\)，在无噪声、跳跃有限时收敛到整个 \\([X]_t\\)（Barndorff-Nielsen 与 Shephard，Econometrica 2004；Andersen、Bollerslev、Diebold 与 Labys，Econometrica 2003）。缺口在于三个「在场者」会把这句话拆开：微观结构噪声让偏差以采样次数 \\(n\\) 增长；跳让 RV 估到的不再是 \\(IV\\)；不同步让协变差的分子塌向零。一族估计量由此长出来；没有地图的人用习惯选——五分钟格走天下——或按文献名气选，都会错对象。</p><p><span class="marginnote">术语翻译：「二次变差」就是把每一小段价格平方变化累加起来的总账。连续波动像匀速磨刀磨出的粉末，一小份一小份累积；跳像一刀砍掉的缺口，一次记一大笔。总账两种都收，「估哪个对象」就是在问你要不要把缺口算进去。</span></p><h3 id="族谱的两根轴" tabindex="-1">族谱的两根轴 <a class="header-anchor" href="#族谱的两根轴" aria-label="Permalink to &quot;族谱的两根轴&quot;">​</a></h3><p>第一根轴是<strong>对象</strong>：估总二次变差，还是只要连续部分 \\(IV\\)，还是要协变差。第二根轴是<strong>容许的干扰</strong>：噪声、跳、不同步，各自把哪些估计量排除掉。两根轴一起出几条主支：朴素 RV 或短采样，只活在没有噪声与跳的世界；跳稳健支——双幂次变差、门限法、半方差——在跳在场时估连续部分；噪声修正支——两尺度、多尺度、预平均、已实现核、拟极大似然——在噪声在场时恢复 \\(IV\\)；两根轴同时需要时，先降噪再检验跳，或用对两者稳健的组合流程。</p>',8)),(e(),n(t,null,{default:a(()=>[i(B,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E8%A6%81%E4%BC%B0%E4%BB%80%E4%B9%88%EF%BC%9F%22%5D%20--%3E%20T%5B%22%E6%80%BB%E4%BA%8C%E6%AC%A1%E5%8F%98%E5%B7%AE%22%5D%0A%20%20Q%20--%3E%20IV%5B%22%E8%BF%9E%E7%BB%AD%E9%83%A8%E5%88%86%20IV%22%5D%0A%20%20Q%20--%3E%20C%5B%22%E5%8D%8F%E5%8F%98%E5%B7%AE%22%5D%0A%20%20T%20--%3E%20A%5B%22%E6%97%A0%E5%B9%B2%E6%89%B0%EF%BC%9A%E6%9C%B4%E7%B4%A0%20RV%20%E6%88%96%E7%9F%AD%E9%87%87%E6%A0%B7%22%5D%0A%20%20IV%20--%3E%20J%7B%22%E8%B7%B3%E5%9C%A8%E5%9C%BA%EF%BC%9F%22%7D%0A%20%20J%20--%3E%7C%22%E6%98%AF%22%7C%20BV%5B%22%E8%B7%B3%E7%A8%B3%E5%81%A5%E6%94%AF%EF%BC%9A%E5%8F%8C%E5%B9%82%E6%AC%A1%E3%80%81%E9%97%A8%E9%99%90%E3%80%81%E5%8D%8A%E6%96%B9%E5%B7%AE%22%5D%0A%20%20J%20--%3E%7C%22%E5%90%A6%22%7C%20N%7B%22%E5%99%AA%E5%A3%B0%E5%9C%A8%E5%9C%BA%EF%BC%9F%22%7D%0A%20%20N%20--%3E%7C%22%E6%98%AF%22%7C%20NC%5B%22%E5%99%AA%E5%A3%B0%E4%BF%AE%E6%AD%A3%E6%94%AF%EF%BC%9A%E4%B8%A4%E5%B0%BA%E5%BA%A6%E3%80%81%E5%A4%9A%E5%B0%BA%E5%BA%A6%E3%80%81%E9%A2%84%E5%B9%B3%E5%9D%87%E3%80%81%E6%A0%B8%22%5D%0A%20%20N%20--%3E%7C%22%E5%90%A6%22%7C%20A%0A%20%20BV%20--%3E%20BOTH%5B%22%E5%99%AA%E5%A3%B0%E4%B9%9F%E5%9C%A8%E5%9C%BA%EF%BC%9A%E5%85%88%E9%99%8D%E5%99%AA%E5%86%8D%E6%A3%80%E9%AA%8C%EF%BC%8C%E6%88%96%E7%BB%84%E5%90%88%E6%B5%81%E7%A8%8B%22%5D%0A%20%20NC%20--%3E%20BOTH%0A%20%20C%20--%3E%20MV%5B%22%E5%A4%9A%E5%85%83%E5%AD%90%E6%A0%91%EF%BC%9A%E5%AF%B9%E9%BD%90%E4%B8%8E%E9%99%8D%E5%99%AA%EF%BC%8C%E8%A7%81%E5%90%8E%E8%AF%BE%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[r(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=A('<p><span class="marginnote">同一个 6.5 小时交易日：1 秒格 \\(n\\approx 23400\\)，5 分钟格 \\(n=78\\)。噪声在场时，这两个 \\(n\\) 算出的 RV 差得没有公共单位——先用签名图判断谁在场，再谈加总。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>族谱的用法是<strong>先诊断，后选支</strong>。横轴采样间隔、纵轴 RV 的签名图是分岔判据：高频端上翘是噪声主导，走噪声修正支；大致平坦则朴素 RV 尚可，转而先问跳。选支之后才轮到支内选择：核形与带宽、预平均窗口、双幂次还是门限，是后课的事。声明对象时把口径写死：日方差还是年化波动、含不含隔夜、中点价还是成交价——<a href="/quant/rv-noise">已实现波动与噪声修正</a>里「隔夜单列」的约定在这里直接沿用。</p><p>不这么做会错在哪：跳在场时用朴素 RV 估「波动率」，估到的是含跳的总变差，HAR 类预报把瞬时的跳当持续的波动，持续性被系统性夸大；噪声在场时把 1 秒数据直接平方加总，读数随采样密度变，同一天两个系统给出两个「波动率」，风控与对冲用哪个都是掷硬币。</p><p><span class="marginnote">常见误区：「五分钟格走天下」。五分钟只是在许多标的上绕开噪声的经验折中，不是定理——跳在场的日子，五分钟 RV 估到的仍是含跳总变差，拿去预报照样把持续性夸大。选支要靠签名图诊断，不靠习惯。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>支路的划分由<strong>收敛率</strong>背书，这是族谱不是清单的原因。无干扰时 RV 的估计误差以 \\(n^{1/2}\\) 缩小；噪声在场时全数据 RV 的偏差项 \\(2n\\sigma_\\varepsilon^2\\) 随 \\(n\\) 爆炸，两尺度估计把它压回 \\(n^{1/4}\\)，多尺度设计把速率推到任意接近 \\(n^{1/2}\\)，核与预平均以调参换同一方向的改善。干扰假设是速率的前提：把相关噪声当 i.i.d.，减法减过头或减不够，\\(IV\\) 被错估；把有限活动的跳假设换成无穷活动，双幂次的极限不再是连续部分。族谱的每条边上都写着「在此假设下才成立」，换边必须重验假设。</p>',7)),(e(),n(t,null,{default:a(()=>[i(B,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%7B%22%E5%B9%B2%E6%89%B0%E6%98%AF%E4%BB%80%E4%B9%88%3F%22%7D%20--%3E%20NONE%5B%22%E6%97%A0%E5%B9%B2%E6%89%B0%3A%20%E6%9C%B4%E7%B4%A0%20RV%2C%20%E8%AF%AF%E5%B7%AE%E6%8C%89%20n%5E(1%2F2)%20%E7%BC%A9%E5%B0%8F%22%5D%0A%20%20Q%20--%3E%20NZ%5B%22%E5%99%AA%E5%A3%B0%3A%20%E5%85%A8%E6%95%B0%E6%8D%AE%20RV%20%E5%81%8F%E5%B7%AE%202n%CF%83%CE%B5%C2%B2%20%E9%9A%8F%20n%20%E7%88%86%E7%82%B8%22%5D%0A%20%20NZ%20--%3E%20TSRV%5B%22TSRV%20%E6%8A%8A%E8%AF%AF%E5%B7%AE%E5%8E%8B%E5%9B%9E%20n%5E(1%2F4)%22%5D%0A%20%20TSRV%20--%3E%20MSRV%5B%22MSRV%20%E6%8E%A8%E5%88%B0%E6%8E%A5%E8%BF%91%20n%5E(1%2F2)%22%5D%0A%20%20Q%20--%3E%20JMP%5B%22%E8%B7%B3%3A%20%E6%9C%B4%E7%B4%A0%20RV%20%E4%BC%B0%E5%88%B0%E7%9A%84%E6%98%AF%E6%80%BB%E5%8F%98%E5%B7%AE%22%5D%0A%20%20JMP%20--%3E%20BPV%5B%22%E5%8F%8C%E5%B9%82%E6%AC%A1%20%2F%20%E9%97%A8%E9%99%90%E4%BB%8D%E6%94%B6%E6%95%9B%E5%88%B0%20IV%22%5D%0A%20%20BPV%20--%3E%20PRE%5B%22%E5%89%8D%E6%8F%90%3A%20%E6%9C%89%E9%99%90%E6%B4%BB%E5%8A%A8%3B%20%E6%8D%A2%E5%81%87%E8%AE%BE%E9%A1%BB%E9%87%8D%E9%AA%8C%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[r(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=A('<p><span class="marginnote">为什么速率要紧：日度 \\(IV\\) 序列最终要喂给风险预算，估计误差就是仓位噪声。朴素 RV 在噪声下的读数随采样密度变——换个数据商、「波动率」就翻倍；选对支路后误差才与采样密度脱钩，下游结果才可复现。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>族谱只排单标的的方差估计；协变差的时钟对齐与正定性是另一棵子树，总图见<a href="/quant/realized-covariance">多元已实现协方差</a>，对齐见<a href="/quant/hayashi-yoshida">Hayashi–Yoshida 相关</a>，本课程后面单开。族谱也不回答「数据怎么洗」：坏 tick 冒充噪声会把诊断带进错误的支路，清洗先于一切估计量。树不裁决同支内谁更好：核形、带宽、窗口的选择靠准则与有限样本实验，不靠发表年份。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>族谱两根轴：估计对象（总变差、连续 \\(IV\\)、协变差）× 容许干扰（噪声、跳、不同步），支路按这两件事分，不按年份分。</li><li>签名图是分岔判据：高频上翘走噪声修正支，平坦先问跳。</li><li>收敛率背书分岔：朴素 RV 在噪声下偏差 \\(2n\\sigma_\\varepsilon^2\\) 爆炸；两尺度压回 \\(n^{1/4}\\)，多尺度接近 \\(n^{1/2}\\)。</li><li>干扰假设是每条边的前提：相关噪声、无穷活动跳都会让支路失效，换边重验。</li><li>对象口径先于估计量：日或年化、含不含隔夜、中点或成交价，写死再动手。</li><li>出处：Barndorff-Nielsen and Shephard, <em>Econometrica</em>, 2004 与 <em>Journal of Financial Econometrics</em>, 2004；Andersen, Bollerslev, Diebold and Labys, <em>Econometrica</em>, 2003；Zhang, Mykland and Aït-Sahalia, <em>JASA</em>, 2005。</li></ul>',5))])}const f=o(d,[["render",h]]);export{V as __pageData,f as default};
